parameters.jsCode:
// PLACEHOLDER — sub-workflow D2 (Serasa Concentre) ainda não construído.
// Endpoint/payload real da Serasa (RELATORIO_INTERMEDIARIO_PJ) ainda não foi validado nesta conversa.
// Por enquanto devolve tudo como ND, sem disparar o Gate G2, pra não travar o fluxo.
return [{ json: {
  t_score: 'ND', t_protestos: 'ND', t_execucoes: 'ND', t_spc: 'ND', gate_disparado: null
} }];

const d1 = $('Executar D1 (Coleta Fiscal)').item.json;
const d2 = $('D2 (PLACEHOLDER — substituir por sub-workflow real)').item.json;
const fornecedorAtualizado = $('Salvar Dados Cadastrais').item.json;
const dados = $('Buscar Tabelas de Pontos').item.json;
const tabelas = dados.tabelas_pontos || {};
const temD5 = Number(dados.respostas_existentes || 0) > 0;

function pontosOpcao(criterio, categoria) {
  const t = tabelas[criterio];
  if (!t) return 0;
  if (categoria in t) return Number(t[categoria]);
  return Number(t['ND'] ?? 0);
}
function pontosBanda(criterio, valor) {
  const t = tabelas[criterio];
  if (!t || !t.bands) return 0;
  if (valor === 'ND' || valor === null || valor === undefined) return Number(t.nd_pontos ?? 0);
  const num = Number(valor);
  if (!Number.isFinite(num)) return Number(t.nd_pontos ?? 0);
  for (const b of t.bands) {
    if (b.max === null || b.max === undefined || num <= b.max) return Number(b.pontos);
  }
  return Number(t.nd_pontos ?? 0);
}

// ---------- D1 (com breakdown) ----------
const d1_subcriterios = [
  { criterio: 'cnd_federal', label: 'CND/CPEN Federal', categoria: d1.t_cnd, pontos: pontosOpcao('cnd_federal', d1.t_cnd) },
  { criterio: 'pgfn', label: 'Dívida ativa PGFN', categoria: d1.t_pgfn, pontos: pontosOpcao('pgfn', d1.t_pgfn) },
  { criterio: 'sintonia', label: 'Receita Sintonia', categoria: 'ND', pontos: pontosOpcao('sintonia', 'ND') },
  { criterio: 'regularidade_estadual_municipal', label: 'Regularidade estadual/municipal', categoria: d1.t_est, pontos: pontosOpcao('regularidade_estadual_municipal', d1.t_est) },
  { criterio: 'obrigacoes_acessorias', label: 'Obrigações acessórias', categoria: 'ND', pontos: pontosOpcao('obrigacoes_acessorias', 'ND') },
];
const s1 = d1_subcriterios.reduce((sum, s) => sum + s.pontos, 0);

// ---------- D2 (com breakdown) ----------
const d2_subcriterios = [
  { criterio: 'serasa_score', label: 'Serasa Score', categoria: d2.t_score, pontos: pontosBanda('serasa_score', d2.t_score) },
  { criterio: 'protestos', label: 'Protestos', categoria: d2.t_protestos, pontos: pontosBanda('protestos', d2.t_protestos) },
  { criterio: 'execucoes_relevantes', label: 'Execuções relevantes', categoria: d2.t_execucoes, pontos: pontosBanda('execucoes_relevantes', d2.t_execucoes) },
  { criterio: 'spc', label: 'Negativação SPC', categoria: d2.t_spc, pontos: pontosOpcao('spc', d2.t_spc) },
];
const s2 = d2_subcriterios.reduce((sum, s) => sum + s.pontos, 0);

// ---------- D3 ----------
const regime = fornecedorAtualizado.regime_tributario || 'ND';
const s3 = pontosOpcao('regime_tributario', regime);
const d3_subcriterios = [
  { criterio: 'regime_tributario', label: 'Regime tributário', categoria: regime, pontos: s3 },
];

// ---------- D4 ----------
const curva = tabelas['dependencia_curva'] || { p0_pct: 2, pmax_pct: 20 };
const valorPago = Number(fornecedorAtualizado.valor_compras_anual || 0);
const faturamentoFornecedor = Number(fornecedorAtualizado.faturamento_estimado || 0);
let s4, d4_nd = false, p_pct = null;
if (faturamentoFornecedor > 0) {
  p_pct = (valorPago / faturamentoFornecedor) * 100;
  const p0 = Number(curva.p0_pct ?? 2);
  const pmax = Number(curva.pmax_pct ?? 20);
  s4 = 100 * Math.max(0, Math.min(1, (pmax - p_pct) / (pmax - p0)));
  s4 = Math.round(s4 * 100) / 100;
} else {
  s4 = 50;
  d4_nd = true;
}
const d4_detalhe = {
  valor_compras_anual: valorPago,
  faturamento_estimado_fornecedor: faturamentoFornecedor || null,
  participacao_pct: p_pct !== null ? Math.round(p_pct * 100) / 100 : null,
  nd: d4_nd,
  pontos: s4,
};

// ---------- Completude ----------
const camposND = [];
if (d1.t_cnd === 'Não obtida') camposND.push('cnd_federal');
if (d1.t_pgfn === 'Não verificado') camposND.push('pgfn');
camposND.push('sintonia', 'obrigacoes_acessorias');
if (d1.t_est === 'ND') camposND.push('regularidade_estadual_municipal');
if (d2.t_score === 'ND') camposND.push('serasa_score');
if (d2.t_protestos === 'ND') camposND.push('protestos');
if (d2.t_execucoes === 'ND') camposND.push('execucoes_relevantes');
if (d2.t_spc === 'ND') camposND.push('spc');
if (d4_nd) camposND.push('dependencia_faturamento');

const totalCampos = 15;
const completude_pct = Math.round(((totalCampos - camposND.length) / totalCampos) * 10000) / 100;

return [{ json: {
  s1_fiscal: s1, s2_financeira: s2, s3_regime: s3, s4_dependencia: s4,
  s5_maturidade: null,
  completude_pct, campos_nd: camposND,
  breakdown: {
    d1: { subcriterios: d1_subcriterios, total: s1, gate_disparado: d1.gate_disparado },
    d2: { subcriterios: d2_subcriterios, total: s2, gate_disparado: d2.gate_disparado },
    d3: { subcriterios: d3_subcriterios, total: s3 },
    d4: d4_detalhe,
  }
} }];

const dims = $('Montar S1-S4 e Completude').item.json;
const score = $('Executar Calcular Score').item.json;

return [{ json: {
  s1_fiscal: dims.s1_fiscal, s2_financeira: dims.s2_financeira,
  s3_regime: dims.s3_regime, s4_dependencia: dims.s4_dependencia,
  s5_maturidade: dims.s5_maturidade,
  completude_pct: dims.completude_pct, campos_nd: dims.campos_nd,
  score_total: score.score_total, decisao: score.decisao, status: score.status,
  preliminar: score.preliminar,
  versao_pesos_id: score.versao_pesos_id, versao_thresholds_id: score.versao_thresholds_id,
  detalhes_calculo: { ...dims.breakdown, pesos_usados: score.pesos_usados }
} }];

